Section HCW.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition isl_call_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo shi : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (h : hdrv) (g : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 t3 t4 t5 t6 m' (k j ver f1 : Z) (mbs tbs j0 j4 jt : list byte),
    ms' = MS (mkR (wz AISL_RET) (Z_to_bv 64 (bv_unsigned sp + -160)) gp tp t0 t1 t2 (wz E) (wz IN)
                  (wz P) (wz (verb_of (zbytes mbs))) (wz p0) (wz k) (wz (p0 + k + 1)) (wz j) (wz ver) (wz E)
                  (wz P) (wz (E + 16)) (wz (p0 + Z.of_nat (length bs))) (wz p0) (wz k) (wz (p0 + k + 1)) (wz j)
                  (wz 2147450880) (wz (Z.shiftr IN 3 + 2147450880)) (wz (Z.shiftr (E + 16) 3 + 2147450880)) t3 t4 t5 t6)
             F (wz P_A_ON_REQUEST_IMPL) fc None m' (seg_rom bsegs)
    /\ munch (isl_Wl lo sp P IN E) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -160)
    /\ rw_cells bsegs m' (bv_unsigned sp + -160) [CB 8 j0; C8 (wz P)]
    /\ rw_cells bsegs m' (bv_unsigned sp + -144) [CB 4 j4; C4 (wz ver)]
    /\ rw_cells bsegs m' (bv_unsigned sp + -136) [C8 (wz (p0 + k + j + 12))]
    /\ rw_cells bsegs m' (bv_unsigned sp + -128) [CB 24 jt]
    /\ rw_cells bsegs m' (bv_unsigned sp + -104) (isl_sv s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
    /\ rw_cells bsegs m' P (ParserCoreCells (mkPC (pc_blim_has c) (pc_blim c) (pc_len c) (pc_len0 c) (pc_skip c) (pc_hlim c) (pc_state c) f1) pad7 pad2)
    /\ (f1 = pc_f c \/ f1 = Z.lor (pc_f c) 16) /\ 0 <= f1 < 2^14
    /\ rw_cells bsegs m' IN [C8 (wz p0)]
    /\ rw_cells bsegs m' E (ErrCodeCells EC_clear)
    /\ rw_cells bsegs m' (P + O_PR_USED) [C1 (b8 0)] /\ rw_cells bsegs m' (P + O_PR_HDR) (HdrCells h)
    /\ bytes_at bsegs m' p0 bs /\ bytes_at bsegs m' p0 mbs /\ bytes_at bsegs m' (p0 + k + 1) tbs
    /\ Z.of_nat (length mbs) = k /\ Z.of_nat (length tbs) = j
    /\ AHttpCat m' g /\ isl_side m P E p0 (Z.of_nat (length bs)) lo shi
    /\ 1 <= k /\ 1 <= j /\ p0 + k + j + 12 <= p0 + Z.of_nat (length bs) /\ (ver = 10 \/ ver = 11).

Definition isl_segA_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo shi : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (h : hdrv) (g : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => isl_ret_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo shi c pad7 pad2 p0 bs h m ms'
          \/ isl_call_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo shi c pad7 pad2 p0 bs h g m ms'.

  Hypothesis MEMCPY : asan_memcpy_stmt.
  Hypothesis ASSIGNA : aassignA_stmt.
  Hypothesis S2V : string_to_verb_stmt.

(* [comment removed for export] *)
Local Ltac isl_take_exit EX :=
  let X := fresh "EX" in
  pose proof EX as X; unfold isl_exit_stmt, kpick, wz in X; cbn [Nat.eqb] in X;
  lazymatch goal with |- evt _ (isl_segA_post ?rav _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _) _ =>
  eapply evt_mono;
