(* [comment removed for export] *)
Lemma pv_call : forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (q I R E lo shi last : Z) (bs : list byte) (r0 : Z) (E0 : ecv) (g : bool),
  bytes_at bsegs m q bs -> last = q + Z.of_nat (length bs) ->
  rw_cells bsegs m I [C8 (wz q)] -> rw_cells bsegs m R [C4 (wz r0)] -> rw_cells bsegs m E (ErrCodeCells E0) ->
  AHttpCat m g -> AXStatics m -> stk bsegs m lo (bv_unsigned sp) -> pv_pure sp q I R E lo shi bs r0 E0 -> mem_inv bsegs m ->
  ACONST m -> stack0 m lo shi -> accessible m q (Z.of_nat (length bs)) -> accessible m E 24 -> shvis m E (E + 24) ->
  evt bsegs (fun ms' => exists t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m',
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 a0' a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (I, I + 8); (R, R + 4); (E, E + 24); (6684368, 6684368 + 64)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ bytes_at bsegs m' q bs
    /\ rw_cells bsegs m' I [C8 (wz (q + pv_adv (pv_out bs)))]
    /\ rw_cells bsegs m' R [C4 (wz (pv_result_cell (pv_out bs) r0))]
    /\ rw_cells bsegs m' E (ErrCodeCells (pv_ec (pv_out bs) E0))
    /\ AHttpCat m' (pv_cat (pv_out bs) g) /\ AXStatics m'
    /\ ACONST m' /\ stack0 m' lo shi)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz I) (wz last) (wz R) (wz E) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
